create database customer_behavior;
use customer_behavior;

select * from customer;
# 1. What is the total revanue generated by male vs female Customer.
select  gender,sum(purchase_amount) 
Total_Revenue_generated
from customer
group by gender;


# 2. Which Customers used a discount but still spent more than the Average purchase amount?
select* from customer
where purchase_amount >(select avg(purchase_amount)from customer where discount_applied='yes');

# 3. Which are the top 5 products with the highest average review rating?
select item_purchased,round(avg(review_rating),2) Avg_review
from customer
group by item_purchased
order by avg(review_rating) desc
limit 5;

# 4. Compare the average purchase amount between standard and express shipping?
select shipping_type,avg(purchase_amount)
from customer
where  shipping_type = 'Express'
union
select shipping_type,avg(purchase_amount)
from customer
where shipping_type = 'standard';

# 5. Do subscribed customers spend more? compare average spend and total revenue subscribers and non subscribers?
select subscription_status,
count(customer_id),
round(avg(purchase_amount),2) avg_spend ,
sum(purchase_amount) Total_Revenue
from customer where subscription_status = 'yes'
union
select subscription_status,
count(customer_id),
round(avg(purchase_amount),2),
sum(purchase_amount) Total_revenue
from customer
where subscription_status = 'no';

# 6. Which 5 products have the highest percentage of purchases with descounts applied?
 select
  item_purchased,
   sum(case when discount_applied = 'yes' then 1 else 0 end)*100/count(*) as percentage_of_purchased
   from customer
group by item_purchased
order by percentage_of_purchased desc
limit 5;

# 7. Segment Customers into new, Returning, and loyal based on their total number of previous purchases and show the count of each segment
select previous_purchases, category,count(*) count_of_segment
from customer
group by category,previous_purchases
order by previous_purchases desc ;


# 8. What are the top 3 most purchases products with each category?
with c as(select category,item_purchased,
count(customer_id) T_order, 
row_number() over(partition by category order by  count(customer_id)) Rnk from customer
group by category,item_purchased
)

select Rnk, category, item_purchased, T_order
from c
where Rnk <= 3;
# 9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe
select subscription_status, count(customer_id)
from customer
where previous_purchases > 5
group by subscription_status;

# 10. What is the revenue contribution of each age group?
select age_group,sum(purchase_amount) revenue_contribution
from customer 
group by age_group
order by revenue_contribution desc;

select subscription_status,count(*)
from customer
group by subscription_status;



